-- Private document boundaries; synthetic fixtures rolled back, no actual file bytes or remote access.
begin;
set local search_path=extensions,public;
select no_plan();
select ok(not has_function_privilege('anon','public.meta_documents_v1(uuid,uuid,uuid,text,uuid,jsonb,uuid)','EXECUTE'),'anonymous document RPC forbidden');
select ok(not has_table_privilege('authenticated','private.meta_document_revisions','INSERT'),'direct revision DML forbidden');
select ok(not has_table_privilege('service_role','private.meta_document_shares','UPDATE'),'privileged key cannot bypass document review commands');
select is((select count(*)::integer from pg_class where oid in('private.meta_documents'::regclass,'private.meta_document_revisions'::regclass,'private.meta_document_links'::regclass,'private.meta_document_shares'::regclass,'private.meta_document_audit'::regclass,'private.meta_document_receipts'::regclass) and relrowsecurity),6,'all private document tables have RLS');
select is((select public from storage.buckets where id='meta-documents'),false,'document bucket is private');
create temp table doc_case(name text primary key,value jsonb);
grant all on doc_case to authenticated;
create function pg_temp.doc_payload() returns jsonb language sql as $$select '{
 "schemaVersion":"2.0","origin":{"facilityId":"c2330000-0000-4000-8000-000000000001"},"destination":{"facilityId":"c2330000-0000-4000-8000-000000000002"},
 "pickupWindow":{"startsAt":"2026-11-02T08:00:00Z","endsAt":"2026-11-02T18:00:00Z"},"deliveryWindow":{"startsAt":"2026-11-03T08:00:00Z","endsAt":"2026-11-03T20:00:00Z"},"acceptedModes":["ROAD"],"requiredEquipment":null,
 "cargoSpecification":{"categoryCode":"GENERAL","description":"Synthetic loading test","packaging":"PALLET","totalWeightKg":1000,"totalVolumeM3":10,"divisible":true,"requirements":[],"units":[{"packageType":"PALLET","quantity":10,"weightPerUnitKg":100,"volumePerUnitM3":1,"dimensionsCm":{"length":100,"width":100,"height":100},"indivisible":true,"stackable":false}]},
 "contacts":{"pickup":{"name":"Example sender","phoneE164":"+12025550123"},"recipient":{"name":"Example recipient","phoneE164":"+12025550124"}}}'::jsonb;$$;
create function pg_temp.doc_call(action text,target uuid default null,value jsonb default '{}',key uuid default null) returns jsonb language sql as $$
 select public.meta_documents_v1('c2300000-0000-4000-8000-000000000001','c2320000-0000-4000-8000-000000000001',null,action,target,value,key);$$;
create function pg_temp.doc_meta() returns jsonb language sql as $$select '{"title":"Synthetic profile","kind":"COMPANY_PROFILE","requestId":null,"documentId":null,"expectedVersion":0,"issuedOn":null,"expiresOn":null,"filename":"profile.pdf","mime":"application/pdf","bytes":312,"sha256":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}'::jsonb;$$;
set local role authenticated;
set local "request.jwt.claims"='{"sub":"c2310000-0000-4000-8000-000000000001","role":"authenticated"}';
insert into doc_case select 'upload',pg_temp.doc_call('upload',null,pg_temp.doc_meta(),'d0510000-0000-4000-8000-000000000001');
select is((select value#>>'{data,state}' from doc_case where name='upload'),'UPLOADING','upload reservation is not a ready document');
select is(pg_temp.doc_call('upload',null,pg_temp.doc_meta(),'d0510000-0000-4000-8000-000000000001'),(select value from doc_case where name='upload'),'upload replay preserves revision and path');
select throws_ok($$select pg_temp.doc_call('upload',null,pg_temp.doc_meta()||'{"title":"changed"}','d0510000-0000-4000-8000-000000000001')$$,'PT409','IDEMPOTENCY_CONFLICT','upload cannot reuse key with other content');
select throws_ok($$select pg_temp.doc_call('finish',(select (value#>>'{data,id}')::uuid from doc_case where name='upload'),'{}','d0510000-0000-4000-8000-000000000002')$$,'PT409','UPLOAD_INCOMPLETE','metadata cannot finalize without private object');
reset role;
insert into storage.objects(bucket_id,name,metadata) select 'meta-documents',value->>'objectPath','{"size":312,"mimetype":"application/pdf"}' from doc_case where name='upload';
set local role authenticated;
insert into doc_case select 'ready',pg_temp.doc_call('finish',(select (value#>>'{data,id}')::uuid from doc_case where name='upload'),'{}','d0510000-0000-4000-8000-000000000002');
select is((select value#>>'{data,state}' from doc_case where name='ready'),'READY','correlated private object can finalize');
select ok(exists(select 1 from jsonb_array_elements(pg_temp.doc_call('library')->'data') d where d->>'id'=(select value#>>'{data,id}' from doc_case where name='ready')),'own library contains the finalized revision without assuming an empty organization');
select lives_ok($$select pg_temp.doc_call('download',(select (value#>>'{data,id}')::uuid from doc_case where name='ready'))$$,'own revision authorized before URL signing');
set local "request.jwt.claims"='{"sub":"c2310000-0000-4000-8000-000000000002","role":"authenticated"}';
select throws_ok($$select pg_temp.doc_call('library')$$,'PT403','FORBIDDEN_WORKFLOW','another subject cannot impersonate organization member');
select throws_ok($$select public.meta_documents_v1('c2300000-0000-4000-8000-000000000002','c2320000-0000-4000-8000-000000000002',null,'download',(select (value#>>'{data,id}')::uuid from doc_case where name='ready'),'{}',null)$$,'PT404','DOCUMENT_NOT_FOUND','other tenant cannot download revision');
set local "request.jwt.claims"='{"sub":"c2310000-0000-4000-8000-000000000001","role":"authenticated"}';
insert into doc_case select 'request',public.create_v2_freight_request('c2300000-0000-4000-8000-000000000001','c2320000-0000-4000-8000-000000000001','d0510000-0000-4000-8000-000000000003',private.hash_v2_freight_payload(pg_temp.doc_payload()),pg_temp.doc_payload());
insert into doc_case select 'link',pg_temp.doc_call('link',(select (value->>'id')::uuid from doc_case where name='request'),jsonb_build_object('revisionId',(select value#>>'{data,id}' from doc_case where name='ready'),'expectedVersion',0),'d0510000-0000-4000-8000-000000000004');
select is(jsonb_array_length(pg_temp.doc_call('dossier',(select (value->>'id')::uuid from doc_case where name='request'))->'data'),1,'organization revision linked to request');
select is(jsonb_array_length((pg_temp.doc_call('dossier',(select (value->>'id')::uuid from doc_case where name='request'))#>'{data,0,shares}')),0,'linking never shares the entire library');
select throws_ok($$select pg_temp.doc_call('link',(select (value->>'id')::uuid from doc_case where name='request'),jsonb_build_object('revisionId',(select value#>>'{data,id}' from doc_case where name='ready'),'expectedVersion',0),'d0510000-0000-4000-8000-000000000005')$$,'PT409','STALE_DOCUMENT_LINK','stale link version rejected');
-- A packing list is request-specific and binds to the current reviewed declaration.
insert into doc_case select 'packing',pg_temp.doc_call('upload',null,pg_temp.doc_meta()||jsonb_build_object('title','Synthetic packing list','kind','PACKING_LIST','requestId',(select value->>'id' from doc_case where name='request')),'d0510000-0000-4000-8000-000000000030');
reset role;
insert into storage.objects(bucket_id,name,metadata) select 'meta-documents',value->>'objectPath','{"size":312,"mimetype":"application/pdf"}' from doc_case where name='packing';
set local role authenticated;
select lives_ok($$select pg_temp.doc_call('finish',(select (value#>>'{data,id}')::uuid from doc_case where name='packing'),'{}','d0510000-0000-4000-8000-000000000031')$$,'packing list file can finish independently of manifest');
select throws_ok($$select pg_temp.doc_call('link',(select (value->>'id')::uuid from doc_case where name='request'),jsonb_build_object('revisionId',(select value#>>'{data,id}' from doc_case where name='packing'),'expectedVersion',0),'d0510000-0000-4000-8000-000000000032')$$,'PT409','CONFIRMED_MANIFEST_REQUIRED','packing list link requires reviewed manifest');
insert into doc_case select 'manifest_preparation',public.meta_declared_manifests_v1('c2300000-0000-4000-8000-000000000001','c2320000-0000-4000-8000-000000000001',(select (value->>'id')::uuid from doc_case where name='request'),'prepare','{"expectedDraftVersion":1,"expectedManifestRevision":0}','d0510000-0000-4000-8000-000000000033',20,0);
insert into doc_case select 'manifest',public.meta_declared_manifests_v1('c2300000-0000-4000-8000-000000000001','c2320000-0000-4000-8000-000000000001',(select (value->>'id')::uuid from doc_case where name='request'),'confirm',jsonb_build_object('preparationId',value#>>'{record,id}','expectedDraftVersion',1,'expectedManifestRevision',0,'contentHash',value#>>'{record,contentHash}','confirmed',true),'d0510000-0000-4000-8000-000000000034',20,0) from doc_case where name='manifest_preparation';
insert into doc_case select 'packing_link',pg_temp.doc_call('link',(select (value->>'id')::uuid from doc_case where name='request'),jsonb_build_object('revisionId',(select value#>>'{data,id}' from doc_case where name='packing'),'expectedVersion',0),'d0510000-0000-4000-8000-000000000032');
select is((select x->>'correspondenceCurrent' from jsonb_array_elements(pg_temp.doc_call('dossier',(select (value->>'id')::uuid from doc_case where name='request'))->'data')x where x#>>'{revision,kind}'='PACKING_LIST'),'true','packing list matches the confirmed material declaration');
select public.command_v2_freight_request('c2300000-0000-4000-8000-000000000001','c2320000-0000-4000-8000-000000000001','d0510000-0000-4000-8000-000000000035',(select (value->>'id')::uuid from doc_case where name='request'),1,'REVISE',jsonb_set(pg_temp.doc_payload(),'{cargoSpecification,description}','"Changed cargo declaration"'));
select is((select x->>'correspondenceCurrent' from jsonb_array_elements(pg_temp.doc_call('dossier',(select (value->>'id')::uuid from doc_case where name='request'))->'data')x where x#>>'{revision,kind}'='PACKING_LIST'),'false','editing material cargo invalidates document correspondence');
select throws_ok($$select pg_temp.doc_call('link',(select (value->>'id')::uuid from doc_case where name='request'),jsonb_build_object('revisionId',(select value#>>'{data,id}' from doc_case where name='packing'),'expectedVersion',1),'d0510000-0000-4000-8000-000000000036')$$,'PT409','STALE_MANIFEST','reattachment cannot silently approve changed cargo');
select public.command_v2_freight_request('c2300000-0000-4000-8000-000000000001','c2320000-0000-4000-8000-000000000001','d0510000-0000-4000-8000-000000000037',(select (value->>'id')::uuid from doc_case where name='request'),2,'REVISE',pg_temp.doc_payload());
reset role;
insert into auth.users(id,email,email_confirmed_at,aud,role) values('d0510000-0000-4000-8000-000000000007','documents-carrier@example.invalid',now(),'authenticated','authenticated');
insert into public.carrier_operators(id,carrier_id,auth_user_id,display_name,role,status,verified_at) values('d0510000-0000-4000-8000-000000000008','c2340000-0000-4000-8000-000000000001','d0510000-0000-4000-8000-000000000007','Synthetic document reviewer','DISPATCHER','ACTIVE',now());
insert into private.v2_catalog_grants(auth_user_id,carrier_id,permission) values('d0510000-0000-4000-8000-000000000007','c2340000-0000-4000-8000-000000000001','CARRIER_EDITOR');
-- Minimal FK-complete commercial records for document authorization only; no commercial workflow is claimed by these fixtures.
insert into public.route_planning_policies(id,organization_id,status,data) values('d0510000-0000-4000-8000-000000000020','c2300000-0000-4000-8000-000000000001','ACTIVE','{}');
insert into public.route_plans(id,organization_id,freight_request_id,status,data,policy_id) select 'd0510000-0000-4000-8000-000000000021','c2300000-0000-4000-8000-000000000001',(value->>'id')::uuid,'PLANNED','{}','d0510000-0000-4000-8000-000000000020' from doc_case where name='request';
insert into public.transport_plan_candidates(id,organization_id,freight_request_id,status,data,route_plan_id,request_version) select 'd0510000-0000-4000-8000-000000000022','c2300000-0000-4000-8000-000000000001',(value->>'id')::uuid,'PLANNED','{}','d0510000-0000-4000-8000-000000000021',1 from doc_case where name='request';
insert into public.selection_decisions(id,organization_id,freight_request_id,status,data,plan_id,selected_by) select 'd0510000-0000-4000-8000-000000000023','c2300000-0000-4000-8000-000000000001',(value->>'id')::uuid,'SELECTED','{}','d0510000-0000-4000-8000-000000000022','c2320000-0000-4000-8000-000000000001' from doc_case where name='request';
select public.command_v2_freight_request('c2300000-0000-4000-8000-000000000001','c2320000-0000-4000-8000-000000000001','d0510000-0000-4000-8000-000000000026',(select (value->>'id')::uuid from doc_case where name='request'),3,'SUBMIT',null);
update public.transport_plan_candidates set request_version=4 where id='d0510000-0000-4000-8000-000000000022';
insert into public.carrier_opportunities(id,organization_id,carrier_id,freight_request_id,parent_id,status,data) select 'd0510000-0000-4000-8000-000000000025','c2300000-0000-4000-8000-000000000001','c2340000-0000-4000-8000-000000000001',(value->>'id')::uuid,'d0510000-0000-4000-8000-000000000022','OPEN','{}' from doc_case where name='request';
set local "request.jwt.claims"='{"sub":"d0510000-0000-4000-8000-000000000007","role":"authenticated"}';
insert into public.v2_carrier_offers(id,organization_id,carrier_id,freight_request_id,parent_id,status,data,plan_id) select 'd0510000-0000-4000-8000-000000000024','c2300000-0000-4000-8000-000000000001','c2340000-0000-4000-8000-000000000001',(value->>'id')::uuid,'d0510000-0000-4000-8000-000000000025','ACTIVE','{"opportunityId":"d0510000-0000-4000-8000-000000000025","planCandidateId":"d0510000-0000-4000-8000-000000000022","source":{"channel":"MANUAL","issuerId":"d0510000-0000-4000-8000-000000000008"}}','d0510000-0000-4000-8000-000000000022' from doc_case where name='request';
set local "request.jwt.claims"='{"sub":"c2310000-0000-4000-8000-000000000001","role":"authenticated"}';

insert into public.v2_bookings(id,organization_id,carrier_id,freight_request_id,status,data,decision_id,offer_id) select 'd0510000-0000-4000-8000-000000000006','c2300000-0000-4000-8000-000000000001','c2340000-0000-4000-8000-000000000001',(value->>'id')::uuid,'AUTHORIZED','{}','d0510000-0000-4000-8000-000000000023','d0510000-0000-4000-8000-000000000024' from doc_case where name='request';
set local role authenticated;
insert into doc_case select 'share',pg_temp.doc_call('share',(select (value->>'id')::uuid from doc_case where name='request'),jsonb_build_object('linkId',(select value->>'id' from doc_case where name='link'),'bookingId','d0510000-0000-4000-8000-000000000006','expectedVersion',1),'d0510000-0000-4000-8000-000000000009');
select is((select value->>'review' from doc_case where name='share'),'PENDING','explicit sharing starts unreviewed');
create function pg_temp.carrier_doc(action text,target uuid,value jsonb default '{}',key uuid default null) returns jsonb language sql as $$select public.meta_documents_v1(null,'d0510000-0000-4000-8000-000000000008','c2340000-0000-4000-8000-000000000001',action,target,value,key);$$;
set local "request.jwt.claims"='{"sub":"d0510000-0000-4000-8000-000000000007","role":"authenticated"}';
select is(jsonb_array_length(pg_temp.carrier_doc('carrier_dossier','d0510000-0000-4000-8000-000000000006')->'data'),1,'carrier sees only the shared revision for its booking');
select throws_ok($$select pg_temp.carrier_doc('library','d0510000-0000-4000-8000-000000000006')$$,'PT403','FORBIDDEN_DOCUMENT','carrier cannot list organization library');
select lives_ok($$select pg_temp.carrier_doc('download',(select (value->>'id')::uuid from doc_case where name='share'))$$,'carrier can download the explicitly shared revision');
insert into doc_case select 'review',pg_temp.carrier_doc('review',(select (value->>'id')::uuid from doc_case where name='share'),'{"expectedVersion":1,"decision":"CORRECTION_REQUESTED","reason":"Please update the company details"}','d0510000-0000-4000-8000-000000000010');
select is((select value->>'review' from doc_case where name='review'),'CORRECTION_REQUESTED','carrier correction is persisted');
select throws_ok($$select pg_temp.carrier_doc('review',(select (value->>'id')::uuid from doc_case where name='share'),'{"expectedVersion":1,"decision":"ACCEPTED","reason":"Reviewed"}','d0510000-0000-4000-8000-000000000011')$$,'PT409','STALE_DOCUMENT_SHARE','concurrent review cannot overwrite newer decision');
select is(pg_temp.carrier_doc('review',(select (value->>'id')::uuid from doc_case where name='share'),'{"expectedVersion":2,"decision":"ACCEPTED","reason":"Reviewed exact revision"}','d0510000-0000-4000-8000-000000000012')->>'review','ACCEPTED','carrier may accept exact shared revision');
reset role;
select is((select status from public.v2_bookings where id='d0510000-0000-4000-8000-000000000006'),'AUTHORIZED','document review never confirms booking');
set local role authenticated;
set local "request.jwt.claims"='{"sub":"c2310000-0000-4000-8000-000000000001","role":"authenticated"}';
select lives_ok($$select pg_temp.doc_call('revoke',(select (value->>'id')::uuid from doc_case where name='request'),jsonb_build_object('shareId',(select value->>'id' from doc_case where name='share'),'expectedVersion',3),'d0510000-0000-4000-8000-000000000013')$$,'shipper can revoke carrier access');
set local "request.jwt.claims"='{"sub":"d0510000-0000-4000-8000-000000000007","role":"authenticated"}';
select throws_ok($$select pg_temp.carrier_doc('download',(select (value->>'id')::uuid from doc_case where name='share'))$$,'PT404','DOCUMENT_NOT_FOUND','revocation blocks new signed download access');
select is(jsonb_array_length(pg_temp.carrier_doc('carrier_dossier','d0510000-0000-4000-8000-000000000006')->'data'),0,'revoked document disappears from carrier listing');
reset role;
select ok((select count(*)>=6 from private.meta_document_audit),'actions have an immutable audit trail');
select throws_ok($$delete from private.meta_document_audit$$,'PT409','IMMUTABLE_LOADING_RECORD','audit cannot be removed');
set local role authenticated;
set local "request.jwt.claims"='{"sub":"c2310000-0000-4000-8000-000000000001","role":"authenticated"}';
insert into doc_case select 'revision2',pg_temp.doc_call('upload',null,pg_temp.doc_meta()||jsonb_build_object('documentId',(select value#>>'{data,documentId}' from doc_case where name='ready'),'expectedVersion',1),'d0510000-0000-4000-8000-000000000014');
select is((select (value#>>'{data,version}')::integer from doc_case where name='revision2'),2,'replacement creates a second revision');
select is((select x#>>'{revision,id}' from jsonb_array_elements(pg_temp.doc_call('dossier',(select (value->>'id')::uuid from doc_case where name='request'))->'data')x where x#>>'{revision,kind}'='COMPANY_PROFILE'),(select value#>>'{data,id}' from doc_case where name='ready'),'linked shipment retains its exact first revision');
select throws_ok($$select pg_temp.doc_call('upload',null,pg_temp.doc_meta()||jsonb_build_object('documentId',(select value#>>'{data,documentId}' from doc_case where name='ready'),'expectedVersion',1),'d0510000-0000-4000-8000-000000000015')$$,'PT409','STALE_DOCUMENT','old library revision cannot overwrite new upload');
reset role;
update public.organization_members set role='REQUESTER' where id='c2320000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select pg_temp.doc_call('library')$$,'PT403','FORBIDDEN_WORKFLOW','requester cannot browse sensitive corporate documents');
reset role;
select * from finish();
rollback;
